{
  "name": "bt_hci_evt_send_entry_info",
  "confidence": "medium",
  "docstring": "Allocates a 16-byte HCI event buffer, populates it from a 48-byte BT context entry, and dispatches it via hci_evt_send.",
  "subsystem": "bt",
  "var_renames": {
    "a1": "bt_ctx",
    "a2": "entry_idx",
    "v4": "evt_buf",
    "v5": "entry"
  },
  "struct_hints": [
    {
      "offset": 113,
      "meaning": "bt_ctx byte copied to event buffer byte 0"
    },
    {
      "offset": 16,
      "meaning": "entry validity flag controlling whether extra fields are emitted"
    },
    {
      "offset": 20,
      "meaning": "entry byte copied to event buffer byte 3 and gates payload copy"
    },
    {
      "offset": 24,
      "meaning": "entry 8-byte block copied to event buffer bytes 4-11"
    },
    {
      "offset": 32,
      "meaning": "entry byte copied to event buffer byte 2 when byte 20 is nonzero"
    },
    {
      "offset": 36,
      "meaning": "entry dword copied to event buffer bytes 12-15"
    }
  ]
}
